(* [comment removed for export] *)
Lemma higher_fit_b_sound : forall maps aZ nZ baseZ,
  higher_fit_b maps aZ nZ baseZ = true ->
  exists g, (g mod page_size = 0)%Z /\ (aZ + nZ <= g)%Z
            /\ (g + nZ <= baseZ)%Z
